package net.civeira.phylax.feature.observe.observedissue.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.observe.observedissue.domain.ObservedIssue;
import net.civeira.phylax.feature.observe.observedissue.domain.valueobject.CountVO;

class CountValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of count of observed issue")
  void test_count_value_holder_assign_plain_value() {
    Object holder = new Object();
    CountValueHolder<Object> value = new CountValueHolder<>(holder);
    Assertions.assertSame(holder, value.count(1), "Setters must return the holder");
    Assertions.assertTrue(value.getCountValue().isPresent(), "The plain value must be stored");
    Assertions.assertEquals(1, value.getCount().orElse(null), "The plain value must be recovered");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of count of observed issue")
  void test_count_value_holder_assign_value_object() {
    Object holder = new Object();
    CountValueHolder<Object> value = new CountValueHolder<>(holder);
    CountVO vo = CountVO.from(1);
    Assertions.assertFalse(value.getCountValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.count(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getCountValue().orElseThrow());
    Assertions.assertSame(holder, value.count(Optional.empty()));
    Assertions.assertFalse(value.getCountValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.count(Optional.of(vo)));
    Assertions.assertSame(vo, value.getCountValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of count of observed issue against the original")
  void test_count_value_holder_read() {
    Object holder = new Object();
    CountValueHolder<Object> value = new CountValueHolder<>(holder);
    CountVO vo = CountVO.from(1);
    CountVO other = CountVO.from(1);
    ObservedIssue original = Mockito.mock(ObservedIssue.class);
    Mockito.when(original.getCountValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readCount(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNull(value.readCount(Optional.empty(), fails),
        "Without value and original there is no result");
    Assertions.assertFalse(fails.isEmpty(), "A required value must be reported as missing");
    value.count(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readCount(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readCount(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of count of observed issue")
  void test_count_value_holder_unset() {
    Object holder = new Object();
    CountValueHolder<Object> value = new CountValueHolder<>(holder);
    CountVO vo = CountVO.from(1);
    value.count(vo);
    Assertions.assertSame(holder, value.unsetCountIfMatches("count_other"));
    Assertions.assertTrue(value.getCountValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetCountIfMatches("count"));
    Assertions.assertFalse(value.getCountValue().isPresent(),
        "The field name must clear the value");
    value.count(vo);
    Assertions.assertSame(holder, value.unsetCount());
    Assertions.assertFalse(value.getCountValue().isPresent(), "Unset must clear the value");
  }
}
